using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class BulkCreateCapacityTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public BulkCreateCapacityTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
        Store.Reset();
    }

    [Fact]
    public async Task BulkCreateRejectsWholeBatchWhenCumulativeExceedsCapacity()
    {
        var client = _factory.CreateClient();
        var agentResp = await client.PostAsJsonAsync("/api/agents", new { name = "Ada", email = "a@example.com", maxOpenTickets = 2 });
        var agent = await agentResp.Content.ReadFromJsonAsync<Agent>();

        var resp = await client.PostAsJsonAsync("/api/tickets/bulk-create", new
        {
            agentId = agent!.Id,
            tickets = new[] { new { subject = "A" }, new { subject = "B" }, new { subject = "C" } }
        });
        Assert.Equal(HttpStatusCode.BadRequest, resp.StatusCode);

        var listed = await client.GetFromJsonAsync<List<Ticket>>($"/api/tickets?agentId={agent.Id}");
        Assert.Empty(listed!);
    }

    [Fact]
    public async Task BulkCreateSucceedsWithinCapacity()
    {
        var client = _factory.CreateClient();
        var agentResp = await client.PostAsJsonAsync("/api/agents", new { name = "Ada", email = "a@example.com", maxOpenTickets = 3 });
        var agent = await agentResp.Content.ReadFromJsonAsync<Agent>();

        var resp = await client.PostAsJsonAsync("/api/tickets/bulk-create", new
        {
            agentId = agent!.Id,
            tickets = new[] { new { subject = "A" }, new { subject = "B" } }
        });
        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
    }
}

